sql_query:
SELECT "Primary endpoint"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Primary endpoint", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Melanoma' AND TRIM(COALESCE("Name of ICI", '')) = 'Pembrolizumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 2';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Primary endpoint" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Primary endpoint", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Melanoma' AND TRIM(COALESCE("Name of ICI", '')) = 'Pembrolizumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 2'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_primary_endpoint_category(source_value) AS "primary_endpoint_category"
FROM base;
